import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_softmax_bias_scale_sigmoid_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void fused_softmax_bias_scale_sigmoid_kernel(
    const float* __restrict__ inp,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int n,
    int c,
    int h,
    int w,
    float scale
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int plane_size = h * w;
    int total_size = n * plane_size;
    if (idx >= total_size) return;

    int batch_i = idx / plane_size;
    int hw_i = idx % plane_size;
    int base_inp = batch_i * c * plane_size + hw_i;

    // Find max for numerical stability
    float max_val = -1e30f;
    for (int channel = 0; channel < c; channel++) {
        float val = inp[base_inp + channel * plane_size];
        if (val > max_val) {
            max_val = val;
        }
    }

    // Compute sum of exp
    float sum_val = 0.0f;
    for (int channel = 0; channel < c; channel++) {
        sum_val += expf(inp[base_inp + channel * plane_size] - max_val);
    }

    // Write output
    for (int channel = 0; channel < c; channel++) {
        float val = inp[base_inp + channel * plane_size];
        val = expf(val - max_val) / sum_val;  // softmax
        val += bias[channel];                // add bias
        val *= scale;                        // scale
        val = 1.0f / (1.0f + expf(-val));    // sigmoid
        out[base_inp + channel * plane_size] = val;
    }
}

torch::Tensor fused_softmax_bias_scale_sigmoid_cuda(
    torch::Tensor x,
    torch::Tensor bias,
    double scale
) {
    TORCH_CHECK(x.is_cuda(), "Input tensor must be CUDA.");
    TORCH_CHECK(bias.is_cuda(), "Bias tensor must be CUDA.");

    int n = x.size(0);
    int c = x.size(1);
    int h = x.size(2);
    int w = x.size(3);

    auto out = torch::zeros_like(x);
    int total = n * h * w;
    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    fused_softmax_bias_scale_sigmoid_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        n, c, h, w,
        static_cast<float>(scale)
    );

    return out;
}
"""

fused_softmax_bias_scale_sigmoid_cpp = r"""
torch::Tensor fused_softmax_bias_scale_sigmoid_cuda(
    torch::Tensor x,
    torch::Tensor bias,
    double scale
);
"""

fused_ops = load_inline(
    name="fused_softmax_bias_scale_sigmoid_ops",
    cpp_sources=fused_softmax_bias_scale_sigmoid_cpp,
    cuda_sources=fused_softmax_bias_scale_sigmoid_source,
    functions=["fused_softmax_bias_scale_sigmoid_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model that fuses softmax, bias addition, scaling, and sigmoid in a single custom CUDA kernel.
    """
    def __init__(
        self,
        in_channels,
        out_channels,
        kernel_size,
        stride,
        padding,
        output_padding,
        bias_shape,
        scaling_factor
    ):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose2d(
            in_channels,
            out_channels,
            kernel_size,
            stride=stride,
            padding=padding,
            output_padding=output_padding
        )
        self.bias = nn.Parameter(torch.randn(bias_shape).cuda())
        self.scaling_factor = scaling_factor
        self.fused_ext = fused_ops

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_ext.fused_softmax_bias_scale_sigmoid_cuda(x, self.bias, self.scaling_factor)
        return x
